export const LangChangeEvent = 'admin-language-change'

export function getLanguage() {
  return localStorage.getItem(LangKey) || 'zh'
}

export function setLanguage(lang) {
  const next = lang === 'en' ? 'en' : 'zh'
  localStorage.setItem(LangKey, next)
  window.dispatchEvent(new CustomEvent(LangChangeEvent, { detail: next }))
  return next
}

export function toggleLanguage() {
  return setLanguage(getLanguage() === 'zh' ? 'en' : 'zh')
}

export function t(key, lang = getLanguage()) {
  return messages[lang]?.[key] || messages.zh[key] || key
}

export function routeTitle(title, lang = getLanguage()) {
  return t(titleKeys[title] || title, lang)
}
